              </legend>
              <p id="notification-help" className="sr-only">
                Select one of the following notification methods.
              </p>
              <div className="radio-group">
                <RadioButton
                  id="email"
                  name="notification-preference"
                  value="Email"
                  label="Email"
                  checked={preference === 'Email'}
                  onChange={handleRadioChange}
                  required
                />
                <RadioButton
                  id="sms"
                  name="notification-preference"
                  value="SMS"
                  label="SMS"
                  checked={preference === 'SMS'}
                  onChange={handleRadioChange}
                  required
