', direction=None, fact=None, file_name='/workspace/sandbox/skills/building-accessible-ui/radio-button-group--framework-react--style-dark/google/gemini-3-flash-preview__s2/app.js', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents='const { useState } = React;

const RadioButton = ({ id, name, value, label, checked, onChange, required }) => (
  <div className="radio-option">
    <input
      type="radio"
      id={id}
      name={name}
      value={value}
      checked={checked}
      onChange={onChange}
      required={required}
    />
    <label htmlFor={id}>{label}</label>
  </div>
);

const App = () => {
  const [preference, setPreference] = useState('');
  const [status, setStatus] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    if (preference) {
      setStatus(`Preference saved: ${preference}`);
    } else {
      setStatus('Please select an option.');
    }
  };

  const handleRadioChange = (e) => {
    setPreference(e.target.value);
    setStatus('');
  };

  return (
    <main id="main-content">
      <h1>Settings</h1>
      <div className="form-container">
        <form onSubmit={handleSubmit} noValidate={false}>
          <div className="form-field">
            <fieldset aria-describedby="notification-help">
              <legend>
                How do you prefer to receive notifications? <span aria-hidden="true">*</span>
              </legend>
              <p id="notification-help" className="sr-only">
                Select one of the following notification methods.
              </p>
              <div className="radio-group">
                <RadioButton
                  id="email"
                  name="notification-preference"
                  value="Email"
                  label="Email"
                  checked={preference === 'Email'}
                  onChange={handleRadioChange}
                  required
                />
                <RadioButton
                  id="sms"
                  name="notification-preference"
                  value="SMS"
                  label="SMS"
                  checked={preference === 'SMS'}
                  onChange={handleRadioChange}
                  required
                />
                <RadioButton
                  id="push"
                  name="notification-preference"
                  value="Push Notifications"
                  label="Push Notifications"
                  checked={preference === 'Push Notifications'}
                  onChange={handleRadioChange}
                  required
                />
              </div>
            </fieldset>
          </div>
          <button type="submit" className="submit-button">
            Save Preference
          </button>
        </form>
        {status && (
          <div 
            className="status-message" 
            role="status" 
            aria-live="polite"
          >
            {status}
          </div>
        )}
      </div>
    </main>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
