const { AxeBuilder } = require('@axe-core/playwright');
const path = require('path');
const http = require('http');
const fs = require('fs');

const PORT = 3000;

// Simple static file server
const server = http.createServer((req, res) => {
  let filePath = '.' + req.url;
  if (filePath === './') {
    filePath = './index.html';
  }

  const extname = String(path.extname(filePath)).toLowerCase();
  const mimeTypes = {
    '.html': 'text/html',
    '.js': 'text/javascript',
    '.css': 'text/css',
  };

  const contentType = mimeTypes[extname] || 'application/octet-stream';

  fs.readFile(filePath, (error, content) => {
    if (error) {
      if (error.code === 'ENOENT') {
        res.writeHead(404);
        res.end('File not found');
      } else {
        res.writeHead(500);
        res.end('Server error: ' + error.code);
      }
    } else {
      res.writeHead(200, { 'Content-Type': contentType });
      res.end(content, 'utf-8');
    }
  });
});

server.listen(PORT, async () => {
  console.log(`Server running at http://localhost:${PORT}/`);

  let browser;
  try {
    browser = await chromium.launch();
    const context = await browser.newContext();
    const page = await context.newPage();

    // Capture console logs
    page.on('console', msg => console.log(`PAGE LOG: ${msg.text()}`));
    page.on('pageerror', err => console.log(`PAGE ERROR: ${err.message}`));

    const url = `http://localhost:${PORT}/index.html`;
    console.log(`Loading page: ${url}`);

    await page.goto(url);

    // Wait for the React app to render.
    console.log('Waiting for React app to render...');
    await page.waitForSelector('#root main', { timeout: 15000 });
    console.log('React app rendered.');

    const results = await new AxeBuilder({ page }).analyze();

    if (results.violations.length > 0 || results.incomplete.length > 0) {
      if (results.violations.length > 0) {
        console.log(`Found ${results.violations.length} accessibility violations:`);
        const summarizedViolations = results.violations.map(v => ({
          id: v.id,
          impact: v.impact,
          description: v.description,
          help: v.help,
          helpUrl: v.helpUrl,
          nodes: v.nodes.map(n => ({
            html: n.html,
            target: n.target,
            failureSummary: n.failureSummary
          }))
        }));
        console.log(JSON.stringify(summarizedViolations, null, 2));
      }

      if (results.incomplete.length > 0) {
        console.log(`Found ${results.incomplete.length} incomplete accessibility checks:`);
        const summarizedIncomplete = results.incomplete.map(v => ({
          id: v.id,
          impact: v.impact,
          description: v.description,
          help: v.help,
          nodes: v.nodes.map(n => ({
            html: n.html,
            target: n.target,
            failureSummary: n.failureSummary
          }))
        }));
        console.log(JSON.stringify(summarizedIncomplete, null, 2));
      }
    } else {
      console.log('No accessibility violations found.');
    }
  } catch (e) {
    console.error('Error during axe-core execution:', e);
    process.exit(1);
  } finally {
    if (browser) {
      await browser.close();
    }
    server.close();
  }
});
